	var in struct {
		Name   *string `json:"name"`
		Active *bool   `json:"active"`
	}
	if !decode(w, r, &in) {
		return
	}
	pl, err := s.store.UpdatePlan(p.OrgID, r.PathValue("id"), func(pl *store.Plan) error {
		if in.Name != nil {
			pl.Name = *in.Name
		}
		if in.Active != nil {
			pl.Active = *in.Active
		}
		return nil
	})
	if err != nil {
