package store

import (
	"sort"
	"time"
)

// AuditFilter narrows the audit events AuditEvents returns. Empty fields match everything. ActorID matches an actor's
// user ID or API key ID.
type AuditFilter struct {
	Action   string
	TargetID string
	ActorID  string
}

// AppendAudit records an audit event, giving it an ID and the UTC time. Audit events are never changed or removed.
func (s *Store) AppendAudit(e AuditEvent) AuditEvent {
	s.mu.Lock()
	defer s.mu.Unlock()
	e.ID = s.newID("aud")
	e.At = e.At.UTC()
	s.audit = append(s.audit, e)
	return e
}

// AuditEvents returns an organization's audit events that match f, newest first.
func (s *Store) AuditEvents(orgID string, f AuditFilter) []AuditEvent {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []AuditEvent{}
	for _, e := range s.audit {
		if e.OrgID != orgID {
			continue
		}
		if f.Action != "" && e.Action != f.Action {
			continue
		}
		if f.TargetID != "" && e.Target.ID != f.TargetID {
			continue
		}
		if f.ActorID != "" && e.Actor.ID != f.ActorID && e.Actor.UserID != f.ActorID {
			continue
		}
		out = append(out, e)
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].At.Equal(out[j].At) {
			return out[i].At.After(out[j].At)
		}
		return out[i].ID > out[j].ID
	})
	return out
}
EOF

