package api

import (
	"encoding/json"
	"net/http"
	"reflect"
	"time"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/store"
)

// auditUpdates are the actions whose entries say which fields changed. Their "changes" is always present, even when empty.
var auditUpdates = map[string]bool{
	"customer.updated": true, "plan.updated": true, "subscription.updated": true, "webhook_endpoint.updated": true,
	"member.role_changed": true, "org.updated": true,
}

// auditSecrets are the fields that never enter the audit log: API key tokens, invite tokens and webhook signing secrets.
var auditSecrets = map[string]bool{"token": true, "secret": true}

// audit records a successful change in the caller's organization's audit log. Call it only once the change has been made.
// changes is nil for actions that are not updates.
func (s *Server) audit(r *http.Request, p auth.Principal, action, targetType, targetID string, changes map[string]store.AuditChange) {
	s.store.AppendAudit(store.AuditEvent{
		OrgID:     p.OrgID,
		Action:    action,
		Actor:     store.AuditActor{Type: "api_key", ID: p.KeyID, UserID: p.UserID},
		Target:    store.AuditTarget{Type: targetType, ID: targetID},
		RequestID: RequestID(r.Context()),
		At:        s.clock.Now(),
		Changes:   changes,
	})
}

// fieldsOf returns an object's JSON fields, so that two versions of it can be compared field by field.
func fieldsOf(v any) map[string]any {
	b, _ := json.Marshal(v)
	var m map[string]any
	_ = json.Unmarshal(b, &m)
	return m
}

// changesBetween returns, for each JSON field whose value differs between before and after, its old and new value.
func changesBetween(before, after map[string]any) map[string]store.AuditChange {
	out := map[string]store.AuditChange{}
	for k, to := range after {
		if from := before[k]; !auditSecrets[k] && !reflect.DeepEqual(from, to) {
			out[k] = store.AuditChange{From: from, To: to}
		}
	}
	for k, from := range before {
		if _, ok := after[k]; !ok && !auditSecrets[k] {
			out[k] = store.AuditChange{From: from}
		}
	}
	return out
}

// auditView is an audit event as the API shows it.
type auditView struct {
	ID        string            `json:"id"`
	Action    string            `json:"action"`
	Actor     store.AuditActor  `json:"actor"`
	Target    store.AuditTarget `json:"target"`
	RequestID string            `json:"request_id"`
	At        time.Time         `json:"at"`
	// Changes is a map, possibly empty, for the update actions and absent for the others.
	Changes any `json:"changes,omitempty"`
}

func viewAudit(e store.AuditEvent) auditView {
	v := auditView{ID: e.ID, Action: e.Action, Actor: e.Actor, Target: e.Target, RequestID: e.RequestID, At: e.At}
	if auditUpdates[e.Action] {
		changes := e.Changes
		if changes == nil {
			changes = map[string]store.AuditChange{}
		}
		v.Changes = changes
	}
	return v
}

func auditKey(e store.AuditEvent) cursor { return cursor{T: e.At, ID: e.ID} }

// listAuditEvents answers the organization's audit log, newest first. ?action= keeps one kind of event, ?target_id= the
// events about one object and ?actor_id= those made by one user or API key (a user ID or an API key ID). Only owners and
// admins may read the log.
func (s *Server) listAuditEvents(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	if !auth.CanManageTeam(p.Role) {
		writeJSON(w, http.StatusForbidden, map[string]string{"error": "forbidden"})
		return
	}
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	evs := s.store.AuditEvents(p.OrgID, store.AuditFilter{Action: q.Get("action"), TargetID: q.Get("target_id"), ActorID: q.Get("actor_id")})
	items, next := pageOfNewest(evs, auditKey, pg)
	views := make([]auditView, 0, len(items))
	for _, e := range items {
		views = append(views, viewAudit(e))
	}
	writeJSON(w, http.StatusOK, list{Items: views, NextCursor: next})
}

// pageOfNewest is pageOf for items sorted newest first: the page holds the items older than the cursor.
func pageOfNewest[T any](items []T, key func(T) cursor, p page) ([]T, string) {
	start := 0
	if p.after != nil {
		start = len(items)
		for i, it := range items {
			if key(it).less(*p.after) {
				start = i
				break
			}
		}
	}
	end := min(start+p.limit, len(items))
	out := items[start:end]
	next := ""
	if end < len(items) && len(out) > 0 {
		next = encodeCursor(key(out[len(out)-1]))
	}
	return out, next
}

