package api_test

import (
	"net/http"
	"reflect"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// idOf returns the "id" of an object the API answered.
func idOf(t *testing.T, r *apitest.Response) string {
	t.Helper()
	id, _ := r.Map(t)["id"].(string)
	if id == "" {
		t.Fatalf("no id in %s", r)
	}
	return id
}

// auditEvents returns the audit events the API lists for key, newest first. query is a query string such as "?limit=100".
func auditEvents(t *testing.T, e *apitest.Env, key, query string) []map[string]any {
	t.Helper()
	var page struct {
		Items []map[string]any `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/audit-events"+query, key, nil, &page)
	return page.Items
}

// expected is an audit event a test expects the log to hold. changes is nil for the actions without changes, and holds
// each changed field's new value for the updates (empty when nothing changed).
type expected struct {
	reqID, action, targetType, targetID string
	at                                  time.Time
	changes                             map[string]any
}

func TestAuditLogRecordsEachKindOfChange(t *testing.T) {
	e := apitest.New(t)
	key := e.Acme.Key
	var want []expected

	// send makes a request as Acme's owner, a second after the previous one, with the request ID reqID, and checks the status.
	send := func(reqID, method, path string, body any, status int) *apitest.Response {
		t.Helper()
		e.Clock.Advance(time.Second)
		r := e.DoWith(method, path, key, body, http.Header{"X-Request-Id": {reqID}})
		if r.Code != status {
			t.Fatalf("%s %s: want %d, got %s", method, path, status, r)
		}
		return r
	}
	// expect records the event the last request must have made.
	expect := func(r *apitest.Response, action, targetType, targetID string, changes map[string]any) {
		t.Helper()
		want = append(want, expected{reqID: r.Header.Get("X-Request-Id"), at: e.Clock.Now(), action: action, targetType: targetType, targetID: targetID, changes: changes})
	}

	r := send("org-1", "PATCH", "/v1/org", map[string]any{"name": "Acme Inc", "tax_rate_bp": 500}, http.StatusOK)
	expect(r, "org.updated", "org", e.Acme.ID, map[string]any{"name": "Acme Inc", "tax_rate_bp": 500.0})

	r = send("cus-1", "POST", "/v1/customers", map[string]string{"name": "Ada", "email": "ada@example.com"}, http.StatusCreated)
	ada := idOf(t, r)
	expect(r, "customer.created", "customer", ada, nil)
	r = send("cus-2", "PATCH", "/v1/customers/"+ada, map[string]string{"name": "Ada L.", "email": "ada@example.com"}, http.StatusOK)
	expect(r, "customer.updated", "customer", ada, map[string]any{"name": "Ada L."})
	r = send("cus-3", "POST", "/v1/customers", map[string]string{"name": "Bob", "email": "bob@example.com"}, http.StatusCreated)
	bob := idOf(t, r)
	expect(r, "customer.created", "customer", bob, nil)
	r = send("cus-4", "DELETE", "/v1/customers/"+bob, nil, http.StatusNoContent)
	expect(r, "customer.deleted", "customer", bob, nil)

	r = send("plan-1", "POST", "/v1/plans", map[string]string{"name": "Pro", "currency": "USD", "price": "10.00", "interval": "month"}, http.StatusCreated)
	plan := idOf(t, r)
	expect(r, "plan.created", "plan", plan, nil)
	r = send("plan-2", "PATCH", "/v1/plans/"+plan, map[string]string{"name": "Pro plus"}, http.StatusOK)
	expect(r, "plan.updated", "plan", plan, map[string]any{"name": "Pro plus"})

	r = send("sub-1", "POST", "/v1/subscriptions", map[string]string{"customer_id": ada, "plan_id": plan}, http.StatusCreated)
	sub := idOf(t, r)
	expect(r, "subscription.created", "subscription", sub, nil)
	r = send("sub-2", "PATCH", "/v1/subscriptions/"+sub, map[string]any{"quantity": 3}, http.StatusOK)
	expect(r, "subscription.updated", "subscription", sub, map[string]any{"quantity": 3.0})
	r = send("sub-3", "POST", "/v1/subscriptions/"+sub+"/cancel", map[string]bool{"at_period_end": true}, http.StatusOK)
	expect(r, "subscription.canceled", "subscription", sub, nil)

	line := []map[string]any{{"description": "Setup", "quantity": 1, "unit_amount": 500}}
	r = send("inv-1", "POST", "/v1/invoices", map[string]any{"customer_id": ada, "currency": "USD", "lines": line}, http.StatusCreated)
	paid := idOf(t, r)
	expect(r, "invoice.created", "invoice", paid, nil)
	r = send("inv-2", "POST", "/v1/invoices/"+paid+"/pay", map[string]string{"payment_method": "pm_card_visa"}, http.StatusOK)
	expect(r, "invoice.paid", "invoice", paid, nil)
	r = send("inv-3", "POST", "/v1/invoices", map[string]any{"customer_id": ada, "currency": "USD", "lines": line}, http.StatusCreated)
	voided := idOf(t, r)
	expect(r, "invoice.created", "invoice", voided, nil)
	r = send("inv-4", "POST", "/v1/invoices/"+voided+"/void", nil, http.StatusOK)
	expect(r, "invoice.voided", "invoice", voided, nil)

	r = send("key-1", "POST", "/v1/api-keys", map[string]string{"name": "CI"}, http.StatusCreated)
	ci := idOf(t, r)
	expect(r, "api_key.created", "api_key", ci, nil)
	r = send("key-2", "DELETE", "/v1/api-keys/"+ci, nil, http.StatusNoContent)
	expect(r, "api_key.revoked", "api_key", ci, nil)

	r = send("invite-1", "POST", "/v1/invites", map[string]string{"email": "new@acme.example", "role": "member"}, http.StatusCreated)
	invite := idOf(t, r)
	expect(r, "invite.created", "invite", invite, nil)
	r = send("invite-2", "DELETE", "/v1/invites/"+invite, nil, http.StatusNoContent)
	expect(r, "invite.revoked", "invite", invite, nil)

	member, _ := e.AddMember(e.Acme, "mem@acme.example", store.RoleMember)
	r = send("member-1", "PATCH", "/v1/members/"+member.ID, map[string]string{"role": "viewer"}, http.StatusOK)
	expect(r, "member.role_changed", "member", member.ID, map[string]any{"role": "viewer"})
	r = send("member-2", "DELETE", "/v1/members/"+member.ID, nil, http.StatusNoContent)
	expect(r, "member.removed", "member", member.ID, nil)

	r = send("hook-1", "POST", "/v1/webhook-endpoints", map[string]any{"url": "https://hooks.acme.example/in", "events": []string{"*"}}, http.StatusCreated)
	hook := idOf(t, r)
	expect(r, "webhook_endpoint.created", "webhook_endpoint", hook, nil)
	r = send("hook-2", "PATCH", "/v1/webhook-endpoints/"+hook, map[string]any{"enabled": false}, http.StatusOK)
	expect(r, "webhook_endpoint.updated", "webhook_endpoint", hook, map[string]any{"enabled": false})
	r = send("hook-3", "DELETE", "/v1/webhook-endpoints/"+hook, nil, http.StatusNoContent)
	expect(r, "webhook_endpoint.deleted", "webhook_endpoint", hook, nil)

	// The log lists the newest first; the actor is Acme's owner's API key in every entry.
	got := auditEvents(t, e, key, "?limit=100")
	if len(got) != len(want) {
		t.Fatalf("the log holds %d events, want %d", len(got), len(want))
	}
	ownerKey, _ := e.Store.APIKeyByToken(key)
	for i, w := range want {
		entry := got[len(got)-1-i]
		if entry["action"] != w.action || entry["request_id"] != w.reqID {
			t.Errorf("event %d: action %v request %v, want %s %s", i, entry["action"], entry["request_id"], w.action, w.reqID)
		}
		if at, err := time.Parse(time.RFC3339Nano, entry["at"].(string)); err != nil || !at.Equal(w.at) {
			t.Errorf("%s: at %v (%v), want %v", w.action, entry["at"], err, w.at)
		}
		wantActor := map[string]any{"type": "api_key", "id": ownerKey.ID, "user_id": e.Acme.Owner.ID}
		if !reflect.DeepEqual(entry["actor"], wantActor) {
			t.Errorf("%s: actor %v, want %v", w.action, entry["actor"], wantActor)
		}
		if target := map[string]any{"type": w.targetType, "id": w.targetID}; !reflect.DeepEqual(entry["target"], target) {
			t.Errorf("%s: target %v, want %v", w.action, entry["target"], target)
		}
		checkChanges(t, w, entry)
	}
}

// checkChanges checks an entry's "changes": present for the updates, holding exactly the expected new values, and absent
// for the other actions.
func checkChanges(t *testing.T, w expected, entry map[string]any) {
	t.Helper()
	got, has := entry["changes"]
	if w.changes == nil {
		if has {
			t.Errorf("%s: has changes %v, want none", w.action, got)
		}
		return
	}
	changes, _ := got.(map[string]any)
	if !has || changes == nil {
		t.Fatalf("%s: changes %v, want an object", w.action, got)
	}
	if len(changes) != len(w.changes) {
		t.Errorf("%s: changes %v, want the fields %v", w.action, changes, w.changes)
	}
	for field, to := range w.changes {
		c, _ := changes[field].(map[string]any)
		if c == nil || !reflect.DeepEqual(c["to"], to) {
			t.Errorf("%s: changes.%s = %v, want to %v", w.action, field, changes[field], to)
		}
	}
}

func TestAuditChangesHoldOldAndNewValues(t *testing.T) {
	e := apitest.New(t)
	ada := e.CreateCustomer(e.Acme, "Ada", "ada@example.com")

	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+ada.ID, e.Acme.Key, map[string]string{"name": "Ada L."}, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/org", e.Acme.Key, map[string]any{"time_zone": "Europe/Paris"}, nil)
	// Nothing changes: the entry is still written, with no changed fields.
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+ada.ID, e.Acme.Key, map[string]string{"name": "Ada L."}, nil)

	got := auditEvents(t, e, e.Acme.Key, "?limit=100")
	if len(got) != 3 {
		t.Fatalf("the log holds %d events, want 3", len(got))
	}
	// Newest first: the no-op customer update, the organization's time zone, the name.
	noop, org, name := got[0]["changes"], got[1]["changes"], got[2]["changes"]
	if !reflect.DeepEqual(noop, map[string]any{}) {
		t.Errorf("the no-op update's changes = %v, want an empty object", noop)
	}
	if want := map[string]any{"time_zone": map[string]any{"from": "America/New_York", "to": "Europe/Paris"}}; !reflect.DeepEqual(org, want) {
		t.Errorf("org changes = %v, want %v", org, want)
	}
	if want := map[string]any{"name": map[string]any{"from": "Ada", "to": "Ada L."}}; !reflect.DeepEqual(name, want) {
		t.Errorf("customer changes = %v, want %v", name, want)
	}
	if _, has := got[0]["changes"]; !has {
		t.Error("the no-op update has no changes field")
	}
}

func TestAuditNeverHoldsSecrets(t *testing.T) {
	e := apitest.New(t)
	var key, invite, hook map[string]any
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", e.Acme.Key, map[string]string{"name": "CI"}, &key)
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "new@acme.example", "role": "admin"}, &invite)
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/in", "events": []string{"*"}}, &hook)
	e.MustDo(http.StatusOK, "PATCH", "/v1/webhook-endpoints/"+hook["id"].(string), e.Acme.Key, map[string]any{"enabled": false}, nil)

	secrets := []string{e.Acme.Key, key["token"].(string), invite["token"].(string), hook["secret"].(string)}
	raw := e.Do("GET", "/v1/audit-events?limit=100", e.Acme.Key, nil)
	if raw.Code != http.StatusOK {
		t.Fatalf("list: %s", raw)
	}
	for _, s := range secrets {
		if strings.Contains(string(raw.Body), s) {
			t.Errorf("the audit log holds the secret %s", s)
		}
	}
}

func TestAuditRecordsNothingForFailedRequests(t *testing.T) {
	e := apitest.New(t)
	gCustomer := e.CreateCustomer(e.Globex, "Globe", "globe@example.com")
	var gHook map[string]any
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Globex.Key, map[string]any{"url": "https://hooks.globex.example/in", "events": []string{"*"}}, &gHook)
	_, viewer := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	acme, globex := len(auditEvents(t, e, e.Acme.Key, "?limit=100")), len(auditEvents(t, e, e.Globex.Key, "?limit=100"))

	failing := []struct {
		name, method, path, key string
		body                    any
	}{
		{"invalid customer", "POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "", "email": "nope"}},
		{"unknown customer", "PATCH", "/v1/customers/cus_nope", e.Acme.Key, map[string]string{"name": "X"}},
		{"another organization's customer", "DELETE", "/v1/customers/" + gCustomer.ID, e.Acme.Key, nil},
		{"another organization's endpoint", "DELETE", "/v1/webhook-endpoints/" + gHook["id"].(string), e.Acme.Key, nil},
		{"unknown invoice", "POST", "/v1/invoices/inv_nope/void", e.Acme.Key, nil},
		{"declined payment", "POST", "/v1/invoices/inv_nope/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_declined"}},
		{"viewer write", "POST", "/v1/plans", viewer, map[string]string{"name": "Pro", "currency": "USD", "price": "1.00", "interval": "month"}},
		{"no key", "POST", "/v1/customers", "", map[string]string{"name": "A", "email": "a@example.com"}},
		{"audit entries are not deletable", "DELETE", "/v1/audit-events/aud_000001", e.Acme.Key, nil},
	}
	for _, f := range failing {
		r := e.Do(f.method, f.path, f.key, f.body)
		if r.Code < 400 {
			t.Fatalf("%s: %s %s answered %s, want an error", f.name, f.method, f.path, r)
		}
	}

	if n := len(auditEvents(t, e, e.Acme.Key, "?limit=100")); n != acme {
		t.Errorf("Acme's log grew from %d to %d on failed requests", acme, n)
	}
	if n := len(auditEvents(t, e, e.Globex.Key, "?limit=100")); n != globex {
		t.Errorf("Globex's log grew from %d to %d on failed requests", globex, n)
	}
	if _, ok := e.Store.WebhookEndpoint(e.Globex.ID, gHook["id"].(string)); !ok {
		t.Error("another organization's endpoint was deleted")
	}
}

func TestAuditLogIsForOwnersAndAdmins(t *testing.T) {
	e := apitest.New(t)
	e.CreateCustomer(e.Acme, "Ada", "ada@example.com")
	_, admin := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	if r := e.Do("GET", "/v1/audit-events", admin, nil); r.Code != http.StatusOK {
		t.Fatalf("admin read: %s", r)
	}
	for _, role := range []store.Role{store.RoleBilling, store.RoleMember, store.RoleViewer} {
		_, key := e.AddMember(e.Acme, string(role)+"@acme.example", role)
		r := e.Do("GET", "/v1/audit-events", key, nil)
		if r.Code != http.StatusForbidden {
			t.Fatalf("%s read: %s", role, r)
		}
		if body := r.Map(t); len(body) != 1 || body["error"] != "forbidden" {
			t.Fatalf("%s read: body %v, want exactly {\"error\":\"forbidden\"}", role, body)
		}
	}
}

func TestAuditLogFiltersAndPages(t *testing.T) {
	e := apitest.New(t)
	_, admin := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	adminKey, _ := e.Store.APIKeyByToken(admin)
	adminUser, _ := e.Store.UserByEmail("admin@acme.example")

	var customers []string
	for _, name := range []string{"A", "B", "C"} {
		c := e.CreateCustomer(e.Acme, name, strings.ToLower(name)+"@example.com")
		customers = append(customers, c.ID)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+customers[0], admin, map[string]string{"name": "A2"}, nil)

	created := auditEvents(t, e, e.Acme.Key, "?action=customer.created&limit=100")
	if len(created) != 3 {
		t.Fatalf("action filter: %d events, want 3", len(created))
	}
	if got := auditEvents(t, e, e.Acme.Key, "?target_id="+customers[0]); len(got) != 2 {
		t.Errorf("target filter: %d events, want 2 (the create and the update)", len(got))
	}
	if got := auditEvents(t, e, e.Acme.Key, "?actor_id="+adminUser.ID+"&limit=100"); len(got) != 4 {
		t.Errorf("actor filter by user: %d events, want 4", len(got))
	}
	if got := auditEvents(t, e, e.Acme.Key, "?actor_id="+adminKey.ID+"&limit=100"); len(got) != 4 {
		t.Errorf("actor filter by key: %d events, want 4", len(got))
	}
	if got := auditEvents(t, e, e.Acme.Key, "?actor_id="+e.Acme.Owner.ID+"&limit=100"); len(got) != 0 {
		t.Errorf("actor filter for the owner: %d events, want 0", len(got))
	}

	// Pages of two, newest first: every customer once, the last created first.
	var seen []string
	cursor := ""
	for {
		query := "?action=customer.created&limit=2"
		if cursor != "" {
			query += "&cursor=" + cursor
		}
		var page struct {
			Items []struct {
				Target store.AuditTarget `json:"target"`
			} `json:"items"`
			NextCursor string `json:"next_cursor"`
		}
		e.MustDo(http.StatusOK, "GET", "/v1/audit-events"+query, e.Acme.Key, nil, &page)
		for _, it := range page.Items {
			seen = append(seen, it.Target.ID)
		}
		if page.NextCursor == "" {
			break
		}
		if len(seen) > len(customers) {
			t.Fatalf("paging does not end: %v", seen)
		}
		cursor = page.NextCursor
	}
	if want := []string{customers[2], customers[1], customers[0]}; !reflect.DeepEqual(seen, want) {
		t.Errorf("paged events %v, want %v", seen, want)
	}

	if got := auditEvents(t, e, e.Globex.Key, "?limit=100"); len(got) != 0 {
		t.Errorf("Globex sees %d of Acme's events", len(got))
	}
}

