func TestAuditLogFiltersAndPages(t *testing.T) {
	e := apitest.New(t)
	_, admin := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	adminKey, _ := e.Store.APIKeyByToken(admin)
	adminUser, _ := e.Store.UserByEmail("admin@acme.example")

	var customers []string
	for _, name := range []string{"A", "B", "C"} {
		c := e.CreateCustomer(e.Acme, name, strings.ToLower(name)+"@example.com")
		customers = append(customers, c.ID)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+customers[0], admin, map[string]string{"name": "A2"}, nil)

	created := auditEvents(t, e, e.Acme.Key, "?action=customer.created&limit=100")
	if len(created) != 3 {
		t.Fatalf("action filter: %d events, want 3", len(created))
	}
	if got := auditEvents(t, e, e.Acme.Key, "?target_id="+customers[0]); len(got) != 2 {
		t.Errorf("target filter: %d events, want 2 (the create and the update)", len(got))
	}
	if got := auditEvents(t, e, e.Acme.Key, "?actor_id="+adminUser.ID+"&limit=100"); len(got) != 4 {
		t.Errorf("actor filter by user: %d events, want 4", len(got))
	}
	if got := auditEvents(t, e, e.Acme.Key, "?actor_id="+adminKey.ID+"&limit=100"); len(got) != 4 {
		t.Errorf("actor filter by key: %d events, want 4", len(got))
	}
	if got := auditEvents(t, e, e.Acme.Key, "?actor_id="+e.Acme.Owner.ID+"&limit=100"); len(got) != 0 {
		t.Errorf("actor filter for the owner: %d events, want 0", len(got))
	}

	// Pages of two, newest first: every customer once, the last created first.
	var seen []string
	cursor := ""
	for {
		query := "?action=customer.created&limit=2"
		if cursor != "" {
			query += "&cursor=" + cursor
		}
		var page struct {
			Items []struct {
				Target store.AuditTarget `json:"target"`
			} `json:"items"`
			NextCursor string `json:"next_cursor"`
		}
		e.MustDo(http.StatusOK, "GET", "/v1/audit-events"+query, e.Acme.Key, nil, &page)
		for _, it := range page.Items {
			seen = append(seen, it.Target.ID)
		}
		if page.NextCursor == "" {
			break
		}
		if len(seen) > len(customers) {
			t.Fatalf("paging does not end: %v", seen)
		}
		cursor = page.NextCursor
	}
	if want := []string{customers[2], customers[1], customers[0]}; !reflect.DeepEqual(seen, want) {
		t.Errorf("paged events %v, want %v", seen, want)
	}

	if got := auditEvents(t, e, e.Globex.Key, "?limit=100"); len(got) != 0 {
		t.Errorf("Globex sees %d of Acme's events", len(got))
	}
}

