package store

import (
	"reflect"
	"testing"
	"time"
)

func TestAuditLog(t *testing.T) {
	s := New()
	acme, err := s.CreateOrg("Acme", OrgTeam, "UTC", 0, t0)
	if err != nil {
		t.Fatal(err)
	}
	globex, err := s.CreateOrg("Globex", OrgTeam, "UTC", 0, t0)
	if err != nil {
		t.Fatal(err)
	}
	first := s.AppendAudit(AuditEvent{OrgID: acme.ID, Action: "customer.created", Actor: AuditActor{Type: "api_key", ID: "key_1", UserID: "usr_1"},
		Target: AuditTarget{Type: "customer", ID: "cus_1"}, At: t0})
	second := s.AppendAudit(AuditEvent{OrgID: acme.ID, Action: "customer.updated", Actor: AuditActor{Type: "api_key", ID: "key_2", UserID: "usr_2"},
		Target: AuditTarget{Type: "customer", ID: "cus_1"}, At: t0, Changes: map[string]AuditChange{"name": {From: "A", To: "B"}}})
	s.AppendAudit(AuditEvent{OrgID: globex.ID, Action: "customer.created", Target: AuditTarget{Type: "customer", ID: "cus_2"}, At: t0})

	if first.ID == "" || first.ID == second.ID {
		t.Fatalf("ids %q and %q", first.ID, second.ID)
	}
	// Newest first; at the same time, the later entry comes first.
	if got := s.AuditEvents(acme.ID, AuditFilter{}); !reflect.DeepEqual(ids(got), []string{second.ID, first.ID}) {
		t.Errorf("events %v, want the newest first", ids(got))
	}
	if got := s.AuditEvents(acme.ID, AuditFilter{ActorID: "usr_2"}); !reflect.DeepEqual(ids(got), []string{second.ID}) {
		t.Errorf("filter by user: %v", ids(got))
	}
	if got := s.AuditEvents(acme.ID, AuditFilter{ActorID: "key_1"}); !reflect.DeepEqual(ids(got), []string{first.ID}) {
		t.Errorf("filter by key: %v", ids(got))
	}
	if got := s.AuditEvents(acme.ID, AuditFilter{Action: "customer.created", TargetID: "cus_1"}); !reflect.DeepEqual(ids(got), []string{first.ID}) {
		t.Errorf("filter by action and target: %v", ids(got))
	}
	if got := s.AuditEvents(globex.ID, AuditFilter{}); len(got) != 1 || got[0].Target.ID != "cus_2" {
		t.Errorf("another organization's events: %v", got)
	}

	// The log survives a snapshot: exporting and rebuilding the store keeps every event.
	rebuilt, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if got := rebuilt.AuditEvents(acme.ID, AuditFilter{}); !reflect.DeepEqual(got, s.AuditEvents(acme.ID, AuditFilter{})) {
		t.Errorf("rebuilt events %+v", got)
	}
}

func ids(es []AuditEvent) []string {
	out := []string{}
	for _, e := range es {
		out = append(out, e.ID)
	}
	return out
}

